const { createHash, randomUUID } = require('crypto');
const sha = value => createHash('sha256').update(value).digest('hex');
const now = new Date().toISOString();
const daysAfter = (date, days) => new Date(Date.parse(date) + days * 86400000).toISOString();
const reply = (httpCode, payload) => ({ httpCode, payload, writes: [] });
const identityError = snapshot => snapshot.actor
  ? reply(403, { status: 'denied' })
  : reply(401, { status: 'authentication_required' });
const put = (collection, row) => ({ collection, row });
const audit = (event, actor, fields) => put('audit', { id: randomUUID(), event, actor, at: now, ...fields });
const clean = value => typeof value === 'string' ? value.trim() : '';
const validDate = value => typeof value === 'string' && Number.isFinite(Date.parse(value)) &&
  new Date(value).toISOString() === value;
const hasScope = (actor, item) => Array.isArray(actor.groups) && Array.isArray(item?.allowed_groups) &&
  item.allowed_groups.length > 0 && item.allowed_groups.every(group => actor.groups.includes(group));
const sameScope = (a, b) => a && b && a.classification === b.classification &&
  JSON.stringify(a.allowed_groups) === JSON.stringify(b.allowed_groups);
const byId = rows => new Map(rows.map(row => [row.id, row]));
const isOpen = review => ['pending', 'clarification_requested'].includes(review.status);

function latestBy(rows, key, order) {
  const latest = new Map();
  for (const row of rows) {
    const previous = latest.get(row[key]);
    if (!previous || previous[order] < row[order]) latest.set(row[key], row);
  }
  return [...latest.values()];
}
const observations = state => latestBy(state.observations, 'knowledge_id', 'last_modified_at');
const authorities = state => latestBy(state.authority, 'stream', 'version');
function evidenceVersion(version, versions) {
  let basis = version;
  let prior = versions.get(basis.supersedes);
  // Renewing verification keeps the decision attached to the same evidence.
  while (prior && prior.observation_id === basis.observation_id) {
    basis = prior;
    prior = versions.get(basis.supersedes);
  }
  return basis.id;
}
const knownClaims = {
  window_hours: /\bwithin (\d{1,4}) hours?\b/gi,
  limit_usd: /\bup to USD (\d{1,6})\b/gi,
  interval_days: /\bevery (\d{1,4}) days?\b/gi
};
function extractClaim(key, content) {
  if (!key) return null;
  const matches = [...content.matchAll(knownClaims[key])];
  const values = [...new Set(matches.map(match => Number(match[1])))];
  if (values.length !== 1 || values[0] <= 0) return null;
  return { key, value: values[0], quote: matches[0][0], offset: matches[0].index };
}
function citation(item) {
  return {
    source_system: item.source_system, source_document_id: item.source_document_id,
    source_url: item.source_url, title: item.title, revision_id: item.id,
    content_hash: item.content_hash, last_modified_at: item.last_modified_at,
    claim: item.claim, provenance: item.provenance
  };
}
function evidenceText(item) {
  if (!item.claim) return item.content;
  const end = item.content.indexOf('.', item.claim.offset + item.claim.quote.length);
  const start = item.content.lastIndexOf('.', item.claim.offset);
  return item.content.slice(start + 1, end < 0 ? undefined : end + 1).trim();
}
function issuePriority(type, record) {
  if (record?.classification === 'restricted' || (type === 'conflict' && record?.topic === 'customer-escalation')) return 'high';
  return 'normal';
}
function verifiedVersion(item, stream, prior, reviewer, verification, approvedAt) {
  const version = (prior?.version ?? 0) + 1;
  return {
    id: stream + ':v' + version, stream, topic: item.topic, department: item.department,
    owner: prior?.owner ?? item.owner, version, supersedes: prior?.id ?? null,
    observation_id: item.id, knowledge_id: item.knowledge_id, title: item.title,
    classification: item.classification, allowed_groups: item.allowed_groups, approval_status: 'approved',
    last_verified_at: verification, review_due_at: approvedAt === 'bootstrap' ? item.source_review_due_at : daysAfter(verification, 90),
    approved_by: reviewer, approved_at: approvedAt === 'bootstrap' ? null : approvedAt,
    confidence: 'owner_verified', claim: item.claim
  };
}

function contributionTopics(snapshot, canRead) {
  const { actor, data, taxonomy } = snapshot;
  const current = authorities(data);
  const source = byId(data.observations);
  const topics = [];
  for (const [topic, [department, , claimKey]] of Object.entries(taxonomy.topics)) {
    if (taxonomy.departments[department] !== actor.id) continue;
    const versions = current.filter(row => row.topic === topic);
    const base = versions[0];
    if (versions.length > 1 || (base && (base.owner !== actor.id || !canRead(source.get(base.observation_id))))) continue;
    const classifications = Object.entries(taxonomy.classifications)
      .filter(([name]) => hasScope(actor, contributionScope(taxonomy, department, name)))
      .map(([name]) => name);
    if (!classifications.length) continue;
    const evidence = base ? source.get(base.observation_id) : null;
    topics.push({ topic, department, classifications: base ? [base.classification] : classifications, claim_key: claimKey,
      base: base ? { id: base.id, version: base.version, title: evidence.title, content: evidence.content,
        type: evidence.knowledge_type } : null });
  }
  return topics;
}

function contributionScope(taxonomy, department, classification) {
  if (!Object.hasOwn(taxonomy.classifications, classification)) return null;
  const group = classification === 'internal' ? 'employees' : taxonomy.departmentGroups[department];
  if (!taxonomy.classifications[classification].includes(group)) return null;
  return { classification, allowed_groups: [group] };
}

function submitContribution(snapshot, request, topics) {
  const { actor, data } = snapshot;
  const input = request || {};
  const topic = topics.find(row => row.topic === input.topic);
  if (!topic) return identityError(snapshot);
  const base = topic.base;
  if (input.base_version_id !== (base?.id ?? null)) {
    return reply(409, { status: 'stale_base', message: 'The published version changed. Refresh the desk and compare your draft with the latest version.' });
  }
  const title = clean(input.title);
  const content = clean(input.content);
  const reason = clean(input.reason);
  const type = input.knowledge_type;
  const claim = extractClaim(topic.claim_key, content);
  const scope = contributionScope(snapshot.taxonomy, topic.department, input.classification);
  const issues = [];
  if (title.length < 4 || title.length > 150) issues.push('Use a title of 4–150 characters.');
  if (content.length < 20 || content.length > 12000) issues.push('Use 20–12,000 characters of knowledge text.');
  if (reason.length < 10 || reason.length > 1000) issues.push('Explain the change in 10–1,000 characters.');
  if (!snapshot.taxonomy.types.includes(type)) issues.push('Choose a knowledge type from the taxonomy.');
  if (!scope || !topic.classifications.includes(scope.classification)) issues.push('Choose an allowed classification. Existing access scope is fixed.');
  if (topic.claim_key && !claim) issues.push('Use one unambiguous policy value in the format shown for this topic.');
  if (issues.length) return reply(422, { status: 'invalid_contribution', message: issues.join(' '), issues });

  const reference = 'contribution:' + topic.topic;
  const rawHash = sha(JSON.stringify([reference, actor.id, base?.id, scope, type, title, content, reason]));
  const reviewId = 'review-' + rawHash.slice(0, 28);
  const existing = data.reviews.find(row => row.id === reviewId);
  if (existing) return reply(200, { status: existing.status, review_id: existing.id, replay: true });
  const open = data.reviews.find(row => row.kind === 'contribution' && row.topic === topic.topic && isOpen(row));
  if (open?.status === 'pending') {
    return reply(409, { status: 'contribution_pending', message: 'A proposal for this topic is already waiting for review.' });
  }
  const head = authorities(data).find(row => row.id === base?.id);
  const id = 'rev-' + rawHash;
  const candidate = {
    id, knowledge_id: 'k-' + sha(reference), source_system: 'contribution', source_document_id: topic.topic,
    source_url: 'https://northstar.example/contribution/' + id, title, content, department: topic.department,
    topic: topic.topic, knowledge_type: type, owner: actor.id, created_at: now, last_modified_at: now,
    source_verified_at: null, source_review_due_at: null, content_hash: sha(content), raw_hash: rawHash,
    ...scope, approval_status: 'observed', confidence: 'source_observation', claim,
    provenance: { adapter: 'review-desk/v1', locator: reference, submitted_by: actor.id, submitted_at: now, review_id: reviewId }
  };
  const review = {
    id: reviewId, kind: 'contribution', topic: topic.topic, department: topic.department, owner: actor.id, submitted_by: actor.id,
    base_ids: head ? [head.id] : [], candidate_id: id, evidence_ids: head ? [head.observation_id, id] : [id],
    explanation: reason, proposed_action: 'A knowledge steward checks the wording, evidence and audience before publication.',
    priority: issuePriority('contribution', candidate), status: 'pending', created_at: now, history: []
  };
  const writes = [put('observations', candidate), put('reviews', review),
    audit('contribution_submitted', actor.id, { topic: topic.topic, review_id: reviewId, observation_id: id })];
  if (open) {
    writes.push(put('reviews', { ...open, status: 'superseded', closed_at: now }),
      audit('review_superseded', actor.id, { topic: topic.topic, review_id: open.id, replaced_by: reviewId }));
  }
  return { ...reply(201, { status: 'pending', review_id: reviewId, topic: topic.topic }), writes };
}

function viewReview(snapshot, request, route) {
  if (!snapshot.actor || snapshot.denied) return identityError(snapshot);
  const state = snapshot.data;
  const actor = snapshot.actor;
  const source = byId(state.observations);
  const versions = byId(state.authority);
  const latest = new Map(observations(state).map(item => [item.knowledge_id, item]));
  const quarantined = new Set(state.quarantine.filter(row => row.status === 'open').map(row => row.id));
  const canRead = item => {
      const head = latest.get(item?.knowledge_id);
      return hasScope(actor, item) && hasScope(actor, head) && !quarantined.has(item.provenance.locator);
  };
  const visible = review => (actor.admin || actor.id === review.owner) &&
    review.evidence_ids.length > 0 && review.evidence_ids.every(id => canRead(source.get(id)));
  const canDecide = review => visible(review) && (review.kind !== 'contribution' ||
    (actor.admin === true && actor.id !== review.submitted_by));
  if (route === 'contribute') return submitContribution(snapshot, request, contributionTopics(snapshot, canRead));
  if (route === 'reviews') {
    const queues = state.reviews.filter(visible).map(review => ({
      ...review,
      can_decide: canDecide(review),
      current: review.base_ids.map(id => versions.get(id)).filter(Boolean).map(version => ({
        version: version.version, verification: version.last_verified_at, claim: version.claim,
        content: source.get(version.observation_id).content
      })),
      proposed: review.candidate_id ? source.get(review.candidate_id).content : null,
      evidence: review.evidence_ids.map(id => {
        const item = source.get(id);
        return { ...citation(item), classification: item.classification,
          authority_rank: snapshot.taxonomy.sourceAuthority[item.source_system],
          approval_status: review.base_ids.some(baseId => versions.get(baseId)?.observation_id === id)
            ? 'approved baseline' : 'source observation',
          excerpt: item.content };
      })
    }));
    const topics = contributionTopics(snapshot, canRead);
    return reply(200, { status: 'ok', reviewer: actor.id, admin: !!actor.admin, reviews: queues,
      contribution: { topics, types: topics.length ? snapshot.taxonomy.types : [] } });
  }
  const { review_id, decision, note } = request || {};
  if (typeof review_id !== 'string' || !/^review-[a-f0-9]{28}$/.test(review_id) ||
      !['approve', 'reject', 'clarify'].includes(decision) || typeof note !== 'string' ||
      clean(note).length < 5 || note.length > 1000) {
    return reply(400, { status: 'invalid_decision', message: 'Choose an action and enter a note of 5–1000 characters.' });
  }
  const review = state.reviews.find(row => row.id === review_id);
  if (!review || !canDecide(review)) {
    return { ...identityError(snapshot), writes: [audit('decision_denied', actor.id, {})] };
  }
  if (!isOpen(review)) return reply(409, { status: 'already_decided' });
  const event = { decision, reviewer: actor.id, at: now, note: clean(note) };
  const updated = { ...review, history: [...review.history, event] };
  const writes = [];
  if (decision === 'approve') {
    const current = authorities(state).filter(row => row.topic === review.topic);
    const base = current[0];
    const candidate = source.get(review.candidate_id);
    const candidateHead = observations(state).find(item => item.knowledge_id === candidate?.knowledge_id);
    const firstPublication = review.kind === 'contribution' && !current.length && !review.base_ids.length;
    const matchingBase = current.length === 1 && review.base_ids.length === 1 && review.base_ids[0] === base.id &&
      candidate?.owner === base.owner && sameScope(candidate, base);
    if ((!firstPublication && !matchingBase) || !candidate || candidateHead?.id !== candidate.id ||
        !candidate.owner || candidate.owner !== snapshot.taxonomy.departments[candidate.department] ||
        (snapshot.taxonomy.topics[review.topic][2] && !candidate.claim)) {
      return reply(409, { status: 'requires_reconciliation', message: 'This evidence, scope or base version changed. Refresh the source and ask the platform steward to reconcile.' });
    }
    const entry = verifiedVersion(candidate, base?.stream || candidate.topic + ':' + candidate.knowledge_id, base, actor.id, now, now);
    updated.status = 'approved';
    updated.resulting_version = entry.id;
    updated.version = entry.version;
    writes.push(put('authority', entry));
    for (const stale of state.reviews.filter(row => row.id !== review.id && row.topic === review.topic &&
        isOpen(row) && (base ? row.base_ids.includes(base.id) : !row.base_ids.length && row.kind === 'contribution'))) {
      writes.push(put('reviews', { ...stale, status: 'superseded', closed_at: now, resulting_version: entry.id }));
      writes.push(audit('review_superseded', actor.id, { review_id: stale.id, topic: stale.topic, version_id: entry.id }));
    }
  } else {
    updated.status = decision === 'reject' ? 'rejected' : 'clarification_requested';
  }
  if (!isOpen(updated)) updated.closed_at = now;
  writes.push(put('reviews', updated), audit('decision_' + decision, actor.id, {
    review_id, topic: review.topic, note: event.note, resulting_version: updated.resulting_version || null
  }));
  return { ...reply(200, { status: updated.status, review_id, reviewer: actor.id, decided_at: now,
    authoritative_version: updated.version ?? null, resulting_version: updated.resulting_version ?? null }), writes };
}

return [{ json: viewReview($json, $('Read Review Desk request').first().json.body, $('Read Review Desk request').first().json.route) }];
